t.script:
// web.layout injecte son titre avant le notre ; le
// navigateur garde le premier. On force le notre.
document.addEventListener('DOMContentLoaded', function () {
    document.title = 'Tour de contrôle — Community';
});

select.style:
font-size:.8rem; padding:.2rem .5rem; border-radius:.4rem;
                                       background:var(--surface); color:inherit;
                                       border:1px solid var(--surface2); cursor:pointer;

div.script:
/* Thème clair/sombre (09/08, Patrick). Même clé localStorage
   que les cockpits : le choix fait ici vaut partout. */
(function () {
    var key = "tour-theme", root = document.documentElement;
    function appliquer(t) { root.setAttribute("data-theme", t); }
    var saved = null;
    try { saved = localStorage.getItem(key); } catch (e) {}
    if (saved === "light" || saved === "dark") appliquer(saved);
    var b = document.getElementById("themebtn");
    if (b) {
        function marquer() {
            var cur = root.getAttribute("data-theme");
            if (!cur) cur = matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
            b.textContent = cur === "dark" ? "☀️ Clair" : "🌙 Sombre";
        }
        b.addEventListener("click", function () {
            var cur = root.getAttribute("data-theme");
            if (!cur) cur = matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
            var next = cur === "dark" ? "light" : "dark";
            appliquer(next);
            try { localStorage.setItem(key, next); } catch (e) {}
            marquer();
        });
        marquer();
    }
})();
(function () {
    var btn = document.getElementById("actions-btn");
    var nav = document.getElementById("menu-actions");
    var ov = document.getElementById("actions-overlay");
    var cl = document.getElementById("menu-close");
    var ouvrir = function () {
        if (nav) nav.classList.add("ouvert");
        if (ov) ov.classList.add("ouvert");
    };
    var fermer = function () {
        if (nav) nav.classList.remove("ouvert");
        if (ov) ov.classList.remove("ouvert");
    };
    if (btn) btn.addEventListener("click", ouvrir);
    if (cl) cl.addEventListener("click", fermer);
    if (ov) ov.addEventListener("click", fermer);
    document.addEventListener("keydown", function (e) {
        if (e.key === "Escape") fermer();
    });
    // Groupes repliables (03/08) : seuls les principaux
    // restent ouverts ; la préférence est mémorisée.
    var CLE = "tdc_menu_ouvert";
    var mem = {};
    try { mem = JSON.parse(localStorage.getItem(CLE) || "{}"); } catch (e) {}
    var groupes = nav ? nav.querySelectorAll(".menu-groupe") : [];
    groupes.forEach(function (g) {
        var cle = g.getAttribute("data-cle");
        var corps = cle ? nav.querySelector(".menu-sous[data-cle='" + cle + "']") : null;
        if (mem[cle] === 1) {
            g.classList.add("ouvert");
            g.setAttribute("aria-expanded", "true");
            if (corps) corps.classList.add("ouvert");
        } else if (mem[cle] === 0) {
            g.classList.remove("ouvert");
            g.setAttribute("aria-expanded", "false");
            if (corps) corps.classList.remove("ouvert");
        }
        g.addEventListener("click", function () {
            var ou = g.classList.toggle("ouvert");
            g.setAttribute("aria-expanded", ou ? "true" : "false");
            if (corps) corps.classList.toggle("ouvert", ou);
            mem[cle] = ou ? 1 : 0;
            try { localStorage.setItem(CLE, JSON.stringify(mem)); } catch (e2) {}
        });

    // Recherche (08/08) : filtre les liens du menu par
    // texte. Quand on tape, chaque groupe ne montre que
    // ses liens qui correspondent ; un groupe sans
    // resultat se masque. Effacer le champ rend l'etat
    // memorise (tous replies par defaut).
    var cherche = document.getElementById("actions-cherche");
    if (cherche && nav) {
        var toutA = nav.querySelectorAll(".menu-sous a");
        var msgAucun = document.createElement("div");
        msgAucun.className = "aucun";
        msgAucun.textContent = "Aucune action ne correspond.";
        nav.insertBefore(msgAucun, nav.querySelector(".menu-groupe") || nav.firstChild);
        var filtrer = function () {
            var q = cherche.value.trim().toLowerCase();
            if (!q) {
                nav.querySelectorAll(".menu-groupe, .menu-sous, .menu-actions a").forEach(function (el) {
                    el.classList.remove("masque");
                });
                msgAucun.classList.remove("visible");
                groupes.forEach(function (g) {
                    var cle = g.getAttribute("data-cle");
                    var corps = nav.querySelector(".menu-sous[data-cle='" + cle + "']");
                    if (mem[cle] === 1) {
                        g.classList.add("ouvert");
                        g.setAttribute("aria-expanded", "true");
                        if (corps) corps.classList.add("ouvert");
                    } else {
                        g.classList.remove("ouvert");
                        g.setAttribute("aria-expanded", "false");
                        if (corps) corps.classList.remove("ouvert");
                    }
                });
                return;
            }
            var vus = 0;
            groupes.forEach(function (g) {
                var cle = g.getAttribute("data-cle");
                var corps = nav.querySelector(".menu-sous[data-cle='" + cle + "']");
                var trouves = 0;
                if (corps) {
                    corps.querySelectorAll("a").forEach(function (a) {
                        var ok = a.textContent.toLowerCase().indexOf(q) !== -1;
                        a.classList.toggle("masque", !ok);
                        if (ok) trouves++;
                    });
                }
                var visible = trouves > 0;
                g.classList.toggle("masque", !visible);
                if (corps) corps.classList.toggle("masque", !visible);
                if (visible) {
                    g.classList.add("ouvert");
                    g.setAttribute("aria-expanded", "true");
                    if (corps) corps.classList.add("ouvert");
                    vus += trouves;
                }
            });
            msgAucun.classList.toggle("visible", vus === 0);
        };
        cherche.addEventListener("input", filtrer);
    }

    });
})();
document.querySelectorAll(".ligne").forEach(function (ligne) {
    var titre = ligne.querySelector(".titre b");
    if (!titre || ligne.querySelector(".copier")) { return; }
    var b = document.createElement("span");
    b.className = "copier";
    b.setAttribute("role", "button");
    b.setAttribute("tabindex", "0");
    b.title = "Copier le titre";
    b.textContent = "⧉";
    var copier = function (ev) {
        // La ligne entiere est un lien : sans ces deux
        // lignes, copier ouvrirait la tache au passage.
        ev.preventDefault();
        ev.stopPropagation();
        var texte = titre.textContent.trim();
        var fini = function () {
            b.classList.add("ok");
            b.textContent = "✓";
            setTimeout(function () {
                b.classList.remove("ok");
                b.textContent = "⧉";
            }, 1200);
        };
        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(texte).then(fini);
        } else {
            // Repli pour les contextes non securises :
            // sans lui, le bouton ne ferait rien du tout
            // et on ne saurait pas pourquoi.
            var z = document.createElement("textarea");
            z.value = texte;
            z.style.position = "fixed";
            z.style.opacity = "0";
            document.body.appendChild(z);
            z.select();
            document.execCommand("copy");
            document.body.removeChild(z);
            fini();
        }
    };
    b.addEventListener("click", copier);
    b.addEventListener("keydown", function (ev) {
        if (ev.key === "Enter" || ev.key === " ") { copier(ev); }
    });
    ligne.appendChild(b);
});

body.script:
// AUTO-RAFRAÎCHISSEMENT : la page rechargée seule — la journée
// bouge, le résumé doit la suivre sans qu'on ait à cliquer.
setTimeout(function () { location.reload(); }, 60000);
